<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Event extends Model{protected $fillable=['title','description','starts_at','ends_at','location','category','image_url','registration_url','created_by','published','featured'];protected $appends=['lifecycle'];protected function casts():array{return ['starts_at'=>'datetime','ends_at'=>'datetime','published'=>'boolean','featured'=>'boolean'];}public function getLifecycleAttribute():string{if(!$this->published)return 'draft';$end=$this->ends_at??$this->starts_at;if($end->isPast())return 'ended';if($this->starts_at->isFuture())return 'upcoming';return 'ongoing';}public function attendees(){return $this->belongsToMany(User::class,'rsvps')->withTimestamps();}public function photos(){return $this->hasMany(EventPhoto::class)->orderBy('sort_order');}}
